using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
namespace SimplePZMapmaker.Web.Services;

[McpServerToolType]
public sealed class McpDesignTools(AgentProjectStore maps,AgentWorldStore worlds,AgentDesignStore tasks,NativeLightingService lighting,GameAssetCatalog assets,StaticModelCatalog models) {
 [McpServerTool(Name="design_parametric_building",ReadOnly=true,UseStructuredContent=true),Description("Generate a counted apartment building and reusable entrance modules without changing a session. Options: entrances1–4, floors1–32, apartmentsPerFloor1–4 per entrance, at most8 units/floor. Returns actual apartments, floors and modules. Put its building into an isolated design task with local coordinates.")]
 public ParametricBuildingResult Parametric(ParametricBuildingOptions options){var result=ParametricBuildings.Create(options);AssetRules.Building(result.Building,assets);return result;}
 [McpServerTool(Name="design_task_create",UseStructuredContent=true),Description("Create an isolated revision-bound design candidate in one map or world section. Replacements add/replace up to16 complete building drafts wholly inside constraints rectangle, including their original bounds. Optional neighborhood constraints generate roads/houses/yards within that same rectangle. Source stays unchanged. Defaults require genuine lighting; allowLights requires an explicitly chosen registered lampModelId. Never unlocks doors or moves furniture.")]
 public object Create(string sessionToken,long expectedRevision,DesignConstraints constraints,Building[]? replacements=null,NeighborhoodConstraints? neighborhood=null,string scope="map",string? memberId=null,string objective="Checked design"){
  var source=Source(sessionToken,expectedRevision,scope,memberId);constraints.Validate(source);var p=NeighborhoodPlanner.Copy(source);
  if(neighborhood is not null){if(neighborhood.X<constraints.X||neighborhood.Y<constraints.Y||(long)neighborhood.X+neighborhood.Width>constraints.X+constraints.Width||(long)neighborhood.Y+neighborhood.Height>constraints.Y+constraints.Height)throw new ArgumentException("The neighborhood must fit inside the checked-design rectangle.");var plan=NeighborhoodPlanner.Create(p,neighborhood);NeighborhoodPlanner.Apply(p,plan);}
  Replace(p,replacements??[],constraints);Source(sessionToken,expectedRevision,scope,memberId);var task=new AgentDesignTask{BaseRevision=expectedRevision,Scope=scope,MemberId=memberId,Objective=objective,Candidate=p,Constraints=constraints};tasks.Save(sessionToken,task,null);return Summary(task,sessionToken);
 }
 [McpServerTool(Name="design_task_read",ReadOnly=true,UseStructuredContent=true),Description("Read isolated checked-design task including its candidate, bounded iteration reports, genuine lighting provenance and proposed repairs. TaskRevision is independent of the source BaseRevision. Nothing is committed.")]
 public AgentDesignTask Read(string sessionToken,string taskId){var task=tasks.Read(sessionToken,taskId);Source(sessionToken,task.BaseRevision,task.Scope,task.MemberId);return task;}
 [McpServerTool(Name="design_task_update",UseStructuredContent=true),Description("Replace/add bounded building drafts in a candidate using exact taskRevision. Clears prior checks so stale evidence cannot authorize a commit. Preserves all terrain and objects outside the constraint rectangle. Source revision remains unchanged.")]
 public object Update(string sessionToken,string taskId,long expectedTaskRevision,Building[] replacements){var task=Read(sessionToken,taskId);TaskRevision(task,expectedTaskRevision);Replace(task.Candidate,replacements,task.Constraints);task.Iterations.Clear();task.Changes.Clear();tasks.Save(sessionToken,task,expectedTaskRevision);return Summary(task,sessionToken);}
 [McpServerTool(Name="design_access_check",ReadOnly=true,UseStructuredContent=true),Description("Read coordinate-based access, furniture/locked-door blockers, real stair landing transitions and unsafe edges at an exact source revision. scope map/world, memberId required for world. Options contain bounded local x/y/width/height and optional signed-level start/end route. Coverage is explicit; no game character is run.")]
 public WalkabilityReport Access(string sessionToken,long expectedRevision,WalkabilityOptions options,string scope="map",string? memberId=null,CancellationToken cancellation=default){var p=Source(sessionToken,expectedRevision,scope,memberId);var result=scope=="map"?WalkabilityAnalyzer.Analyze(p,options,cancellation,Properties):WalkabilityAnalyzer.World(worlds.Read(sessionToken).World,memberId!,options,cancellation,Properties);Source(sessionToken,expectedRevision,scope,memberId);return result;}
 [McpServerTool(Name="design_task_check",UseStructuredContent=true),Description("Check an isolated task against authored pedestrian access and, when requested, authentic installed LightingJNI. Records coverage, lighting crop/scenario/provenance, min/average/dark fraction of authored interior cells. Inaccessible drafts block native lighting until repaired; native failures are recorded, never replaced by an estimate. Does not commit.")]
 public async Task<object> Check(string sessionToken,string taskId,long expectedTaskRevision,CancellationToken cancellation=default){var task=Read(sessionToken,taskId);TaskRevision(task,expectedTaskRevision);await Evaluate(sessionToken,task,[],cancellation);Source(sessionToken,task.BaseRevision,task.Scope,task.MemberId);tasks.Save(sessionToken,task,expectedTaskRevision);return Summary(task,sessionToken);}
 [McpServerTool(Name="design_task_repair",UseStructuredContent=true),Description("Bounded design/check/repair loop on an isolated candidate. Tries permitted unedited wall→door connections and unobstructed native stairs, then optionally chosen registered native lamps. Checks after every change; stops on pass, no safe improvement, cancellation or iteration/change limits. Furniture and locked doors are preserved. Signed lighting crop is checked by LightingJNI. Returns review URL and evidence; commit remains separate.")]
 public async Task<object> Repair(string sessionToken,string taskId,long expectedTaskRevision,CancellationToken cancellation=default){
  var task=Read(sessionToken,taskId);TaskRevision(task,expectedTaskRevision);using var timeout=CancellationTokenSource.CreateLinkedTokenSource(cancellation);timeout.CancelAfter(TimeSpan.FromMinutes(4));var token=timeout.Token;
  Func<MapProject,MapProject>? projection=null;if(task.Scope=="world"){var snapshot=worlds.Read(sessionToken);Revision(snapshot.Revision,task.BaseRevision);var sharedWorld=snapshot.World;var member=sharedWorld.Maps.Single(m=>m.Id==task.MemberId);projection=p=>{member.Project=p;return WorldAssembler.ProjectSection(sharedWorld,member);};}
  await Evaluate(sessionToken,task,[],token);
  for(var n=0;n<task.Constraints.MaximumIterations&&task.Changes.Count<task.Constraints.MaximumChanges;n++){
   token.ThrowIfCancellationRequested();if(task.Passed)break;if(task.Iterations.Count>=30)break;var c=task.Constraints;var before=task.Iterations[^1];var access=AccessRepair.Step(task.Candidate,c.Crop(),c.AllowNewDoors,c.AllowStairs,c.AllowEditedEdges,token,projection,Properties);DesignChange? change=null;MapProject? beforeLight=null;
   if(access is not null){task.Candidate=access.Project;change=new("access",access.Change,access.X,access.Y,access.Z);}
   else if(c.AllowLights&&before.Access.Complete&&!before.Access.Issues.Any(i=>i.Severity=="error")&&before.LightingStatus=="checked"&&before.DarkFraction>0){beforeLight=NeighborhoodPlanner.Copy(task.Candidate);change=AddLight(task);}
   if(change is null)break;task.Changes.Add(change);await Evaluate(sessionToken,task,[change],token);
   if(beforeLight is not null){var after=task.Iterations[^1];var improved=after.Access.Complete&&!after.Access.Issues.Any(i=>i.Severity=="error")&&after.LightingStatus=="checked"&&(after.DarkFraction<before.DarkFraction-1e-7||after.Minimum>before.Minimum+1e-7||after.Average>before.Average+1e-7);if(!improved){var rejected=new DesignChange("light-rejected","The proposed lamp did not improve the genuine field; it was removed.",change.X,change.Y,change.Z);task.Iterations[^1]=after with{Changes=[rejected],Passed=false};task.Changes.RemoveAt(task.Changes.Count-1);task.Candidate=beforeLight;await Evaluate(sessionToken,task,[],token);break;}}
  }
  Source(sessionToken,task.BaseRevision,task.Scope,task.MemberId);tasks.Save(sessionToken,task,expectedTaskRevision);return Summary(task,sessionToken);
 }
 [McpServerTool(Name="design_task_commit",UseStructuredContent=true),Description("Commit only the latest passing, complete checked candidate against its original source revision and exact taskRevision. Revalidates installed assets and physical structure. Optional lighting must have passed with genuine provenance. Browser reviews the resulting session revision and receives it as one undoable change. An unresolved/incomplete task is rejected.")]
 public object Commit(string sessionToken,string taskId,long expectedTaskRevision){var task=Read(sessionToken,taskId);TaskRevision(task,expectedTaskRevision);if(!task.Passed)throw new ArgumentException("This task has no current complete passing check. Resolve reported issues and run its checks before committing.");if(task.Constraints.RequireLighting)lighting.VerifyProvenance(task.Iterations[^1].Lighting!.Value.GetProperty("provenance"));ValidateMap(task.Candidate);if(task.Scope=="map"){var s=maps.Mutate(sessionToken,task.BaseRevision,p=>CopyInto(task.Candidate,p),"agent");return new{s.Revision,task.Id};}var world=worlds.Mutate(sessionToken,task.BaseRevision,w=>{var member=w.Maps.Single(m=>m.Id==task.MemberId);member.Project=NeighborhoodPlanner.Copy(task.Candidate);WorldEndpoints.Validate(w,assets,models);});return new{world.Revision,task.Id};}
 MapProject Source(string token,long revision,string scope,string? member){if(scope=="map"&&member is null){var s=maps.Read(token);Revision(s.Revision,revision);return s.Project;}if(scope=="world"&&member is not null){var s=worlds.Read(token);Revision(s.Revision,revision);return s.World.Maps.SingleOrDefault(m=>m.Id==member)?.Project??throw new ArgumentException("World section not found.");}throw new ArgumentException("Choose map or world scope, with a memberId for world tasks.");}
 void Replace(MapProject p,Building[] replacements,DesignConstraints c){if(replacements is null||replacements.Length>16||replacements.Any(b=>b is null)||replacements.Select(b=>b.Id).Distinct().Count()!=replacements.Length)throw new ArgumentException("Provide up to16 distinct building drafts.");bool Inside(Building b)=>b.X>=c.X&&b.Y>=c.Y&&(long)b.X+b.Width<c.X+c.Width&&(long)b.Y+b.Height<c.Y+c.Height;foreach(var b in replacements){var old=p.Buildings.SingleOrDefault(a=>a.Id==b.Id);if(!Inside(b)||old is not null&&!Inside(old))throw new ArgumentException("Both original and replacement building bounds must lie inside the task rectangle, including their exterior edges.");AssetRules.Building(b,assets,false);ModelRules.Building(b,models);if(old is not null)p.Buildings.Remove(old);p.Buildings.Add(NeighborhoodPlanner.Copy(b));}}
 async Task Evaluate(string token,AgentDesignTask task,List<DesignChange> changes,CancellationToken cancellation){
  if(task.Iterations.Count>=32)throw new ArgumentException("The task has32 recorded checks. Create another task to continue.");var c=task.Constraints;var projected=task.Candidate;WorldProject? world=null;if(task.Scope=="world"){var snapshot=worlds.Read(token);world=snapshot.World;Revision(snapshot.Revision,task.BaseRevision);world.Maps.Single(m=>m.Id==task.MemberId).Project=NeighborhoodPlanner.Copy(task.Candidate);projected=WorldAssembler.ProjectSection(world,world.Maps.Single(m=>m.Id==task.MemberId));}
  var access=WalkabilityAnalyzer.Analyze(projected,c.Crop(),cancellation,Properties);string status=c.RequireLighting?"blocked-by-access":"not-requested";string? error=null;JsonElement? field=null;double? min=null,avg=null,dark=null;
  var accessOk=access.Complete&&!access.Issues.Any(i=>i.Severity=="error");if(c.RequireLighting&&accessOk){try{
   var result=await lighting.Check(new(){Project=world is null?task.Candidate:null,World=world,MemberId=task.MemberId,X=c.LightingX,Y=c.LightingY,Size=c.LightingSize,Level=c.LightingLevel,SkyRgb=c.SkyRgb,Ambient=c.Ambient,RoomLightsPowered=c.RoomLightsPowered,Revision=task.BaseRevision+":"+task.TaskRevision},cancellation);field=JsonSerializer.SerializeToElement(result,NativeMapExporter.JsonOptions);var values=InteriorCells(projected,c,field.Value).Select(cell=>(cell[3]+cell[4]+cell[5])/3).ToArray();if(values.Length==0){status="incomplete";error="The selected lighting crop/floor has no authored interior cells. Select the intended rooms.";}else{min=values.Min();avg=values.Average();dark=(double)values.Count(v=>v<c.MinimumLight)/values.Length;status="checked";}
  }catch(ArgumentException e){status="unavailable";error=e.Message;}}
  task.Iterations.Add(new(task.Iterations.Count+1,access,status,error,min,avg,dark,field,changes,accessOk&&(!c.RequireLighting||status=="checked"&&dark==0)));
 }
 static IEnumerable<double[]> InteriorCells(MapProject p,DesignConstraints c,JsonElement field){foreach(var value in field.GetProperty("cells").EnumerateArray()){var cell=value.EnumerateArray().Select(v=>v.GetDouble()).ToArray();var x=c.LightingX+(int)cell[0];var y=c.LightingY+(int)cell[1];if(p.Buildings.Any(b=>b.Design is {} d&&c.LightingLevel>=d.MinLevel&&c.LightingLevel<d.MinLevel+d.Floors.Count&&BuildingDesigner.Cell(b,d.Floors[c.LightingLevel-d.MinLevel],x-b.X,y-b.Y)!='.'))yield return cell;}}
 DesignChange? AddLight(AgentDesignTask task){var c=task.Constraints;var field=task.Iterations[^1].Lighting;if(field is null)return null;var cells=InteriorCells(task.Candidate,c,field.Value).Where(a=>(a[3]+a[4]+a[5])/3<c.MinimumLight).OrderBy(a=>a[3]+a[4]+a[5]);foreach(var cell in cells){var x=c.LightingX+(int)cell[0];var y=c.LightingY+(int)cell[1];foreach(var b in task.Candidate.Buildings){if(b.Design is not{} d||c.LightingLevel<d.MinLevel||c.LightingLevel>=d.MinLevel+d.Floors.Count)continue;var fi=c.LightingLevel-d.MinLevel;var f=d.Floors[fi];var lx=x-b.X;var ly=y-b.Y;if(BuildingDesigner.Cell(b,f,lx,ly)=='.'||BuildingDesigner.StairSpace(b,fi,lx,ly)||f.Objects.SelectMany(BuildingObjects.Cells).Any(a=>a.X==lx&&a.Y==ly)||f.StaticModels.Any(m=>StaticModelPlacement.FootprintCells(m).Any(c=>m.X+c.Dx==lx&&m.Y+c.Dy==ly)))continue;var lamp=models.Placement(c.LampModelId!);lamp.Profile="light";lamp.X=lx;lamp.Y=ly;lamp.Z=c.LightingLevel;lamp.Light=new(){Radius=10,Rgb=[1,.92,.8],Active=true};f.StaticModels.Add(lamp);b.Modified=true;task.Candidate.Version=Math.Max(9,task.Candidate.Version);return new("light","Added the selected registered native lamp in a dark interior cell.",x,y,c.LightingLevel);}}return null;}
 IReadOnlyDictionary<string,string> Properties(string id)=>assets.Ready?assets.Get(id).Properties:new Dictionary<string,string>();
 void ValidateMap(MapProject p){AssetRules.Project(p,assets);models.Validate(p);}
 static void CopyInto(MapProject source,MapProject target){var copy=NeighborhoodPlanner.Copy(source);foreach(var property in typeof(MapProject).GetProperties().Where(p=>p.CanWrite&&p.Name!=nameof(MapProject.SharedInfrastructure)))property.SetValue(target,property.GetValue(copy));}
 static void TaskRevision(AgentDesignTask task,long expected)=>Revision(task.TaskRevision,expected);
 static void Revision(long actual,long expected){if(actual!=expected)throw new AgentRevisionConflict(actual);}
 public static object Summary(AgentDesignTask task,string? token=null)=>new{task.Id,task.Scope,task.MemberId,task.BaseRevision,task.TaskRevision,task.Objective,task.Passed,task.Constraints,task.Changes,iterations=task.Iterations.Select(i=>new{i.Number,i.Access,i.LightingStatus,i.LightingError,i.Minimum,i.Average,i.DarkFraction,i.Changes,i.Passed,provenance=i.Lighting?.GetProperty("provenance")}),reviewUrl="/api/agent/design/"+(token is null?"":token+"/")+task.Id};
}
